'{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "description": "P28 C / V4 the data nightmare (8 answers, one each) and the sign-off; hover a bar for its card.",
 "width": 1237,
 "height": 240,
 "padding": 0,
 "autosize": "none",
 "signals": [
  {
   "name": "t0",
   "init": "now()"
  },
  {
   "name": "clock",
   "init": "0",
   "on": [
    {
     "events": {
      "type": "timer",
      "throttle": 40
     },
     "update": "min(now() - t0, 4600)"
    }
   ]
  },
  {
   "name": "t",
   "update": "min(1, clock / 4500)"
  },
  {
   "name": "nmax",
   "update": "length(data(''mx'')) ? max(1, data(''mx'')[0].m) : 1"
  },
  {
   "name": "hovN",
   "value": null,
   "on": [
    {
     "events": "@bar:mouseover, @nlab:mouseover, @nval:mouseover",
     "update": "datum"
    },
    {
     "events": "@bar:mouseout, @nlab:mouseout, @nval:mouseout",
     "update": "null"
    }
   ]
  }
 ],
 "data": [
  {
   "name": "dataset"
  },
  {
   "name": "short",
   "values": [
    {
     "k": "It arrives a mess (missing values, duplicates, inconsistent formats)",
     "s": "It arrives a mess"
    },
    {
     "k": "It exists in too many versions (no clear source of truth)",
     "s": "Too many versions"
    },
    {
     "k": "It doesn’t add up (conflicting numbers and mysterious totals)",
     "s": "It doesn’t add up"
    },
    {
     "k": "It takes forever (painfully slow processing or queries)",
     "s": "It takes forever"
    },
    {
     "k": "It falls into the wrong hands (inappropriate access to sensitive data)",
     "s": "Falls into the wrong hands"
    },
    {
     "k": "The AI confidently gets it wrong (unreliable answers or predictions)",
     "s": "The AI gets it wrong"
    },
    {
     "k": "It never arrives (broken pipelines and failed refreshes)",
     "s": "It never arrives"
    },
    {
     "k": "We spot the problem too late (missed events and warnings)",
     "s": "We spot it too late"
    }
   ]
  },
  {
   "name": "rows",
   "source": "dataset",
   "transform": [
    {
     "type": "formula",
     "as": "n",
     "expr": "datum[''Nightmare Respondents''] || 0"
    },
    {
     "type": "lookup",
     "from": "short",
     "key": "k",
     "fields": [
      "dataNightmare"
     ],
     "values": [
      "s"
     ],
     "as": [
      "s0"
     ]
    },
    {
     "type": "formula",
     "as": "lab",
     "expr": "datum.s0 || datum.Nightmare"
    },
    {
     "type": "window",
     "sort": {
      "field": [
       "n",
       "lab"
      ],
      "order": [
       "descending",
       "ascending"
      ]
     },
     "ops": [
      "row_number"
     ],
     "as": [
      "r"
     ]
    },
    {
     "type": "formula",
     "as": "y",
     "expr": "58 + (datum.r - 0.5) * 22.5"
    }
   ]
  },
  {
   "name": "mx",
   "source": "rows",
   "transform": [
    {
     "type": "aggregate",
     "ops": [
      "max"
     ],
     "fields": [
      "n"
     ],
     "as": [
      "m"
     ]
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 28
     },
